'use strict';const $=id=>document.getElementById(id);let worker=null,training=false;
function stop(reason='Stopped. Current weights remain available.'){training=false;if(worker)worker.postMessage({type:'stop'});$('train').disabled=false;$('stop').disabled=true;$('training-status').textContent=reason;}
$('train').onclick=()=>{if(worker)worker.terminate();worker=new Worker('hello-worker.js');training=true;$('train').disabled=true;$('stop').disabled=false;$('weights').disabled=true;$('loss-record').textContent='';$('training-status').textContent='Training locally in a browser worker…';worker.onmessage=e=>{const m=e.data;if(m.type==='progress'){$('training-progress').value=m.step;$('prediction').textContent=m.output||'(empty prediction)';$('loss-record').textContent+=`Step ${String(m.step).padStart(3)}   loss ${m.loss.toFixed(6)}\n`;$('loss-record').scrollTop=$('loss-record').scrollHeight;$('weights').disabled=false;}else if(m.type==='done'){stop('Training complete in '+(m.milliseconds/1000).toFixed(2)+' seconds, including intentional pauses. This is memorization of one phrase.');}else if(m.type==='weights'){const url=URL.createObjectURL(new Blob([JSON.stringify(m.value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='familiar-hello-transformer.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}};worker.onerror=e=>stop('Training failed: '+e.message);worker.postMessage({type:'train'});};$('stop').onclick=()=>stop();$('weights').onclick=()=>worker&&worker.postMessage({type:'weights'});document.addEventListener('visibilitychange',()=>{if(document.hidden&&training)stop('Paused by stopping training because the tab was hidden. Train again to restart.');});
